export async function readMastermindProtectedSpellWardAdoptedInput(cap:MastermindProtectedSpellWardOriginal){
 const fact=await readMastermindProtectedSpellWardSavingOriginal(cap),rows=fact.current.parent.windows[fact.index]?.wardRequests?.filter(row=>row.retargetStep===fact.step)??[];
 if(rows.length!==1)throw Error('spell-ward:single-protected-saving-required');const row=rows[0];
 if(!row.complete||!row.raw||!row.confirmed||row.wardEffectId!==fact.requirement.effect.id||row.wardTargetTokenId!==fact.view.wardTargetId||row.mode!==fact.requirement.mode||row.count!==(fact.requirement.mode==='normal'?1:2)||row.sides!==20||row.rollerTokenId!==fact.current.p.actorToken.id||row.rollerCharacterId!==fact.current.p.actor.id||row.rollerMemberId!==fact.current.parent.original.actorMemberId)throw Error('spell-ward:actual-locked-saving-required');
 const values=[...row.confirmed.values];if(values.length!==row.count||values.some(face=>!Number.isSafeInteger(face)||face<1||face>20))throw Error('spell-ward:exact-locked-saving-required');
 return{fact,row:structuredClone(row),saving:Object.freeze({effectId:row.wardEffectId,d20:values[0],...(row.count===2?{d20Second:values[1]}:{})})}
}
